const test = require('node:test');
const assert = require('node:assert/strict');
const { addCampaign } = require('../campaign.cjs');
test('campaign is a query item, never fragment data', () => {
  let u = new URL(addCampaign('https://tickets.invalid/show#seats', 'spring'));
  assert.equal(u.searchParams.get('campaign'), 'spring');
  assert.equal(u.hash, '#seats');
  u = new URL(addCampaign('https://tickets.invalid/show?zone=west#seats', 'A&B + 中'));
  assert.deepEqual([...u.searchParams], [['zone','west'], ['campaign','A&B + 中']]);
  assert.equal(u.hash, '#seats');
});
test('appends, including duplicate and empty values', () => {
  const u = new URL(addCampaign('https://tickets.invalid/show?campaign=old&x=1', ''));
  assert.deepEqual([...u.searchParams], [['campaign','old'],['x','1'],['campaign','']]);
  assert.equal(new URL(addCampaign('https://tickets.invalid/show', 'new')).searchParams.get('campaign'), 'new');
});

test('preserves the destination as well as query and fragment', () => {
  for (const address of [
    'https://tickets.invalid/show?zone=west#seats',
    'https://sales.invalid:8443/tours/day%202?x=1&x=2#details',
    'https://tickets.invalid/other?',
    'https://tickets.invalid/show#?section=balcony'
  ]) {
    const before = new URL(address);
    const result = new URL(addCampaign(address, 'A&B + 中'));
    assert.equal(result.origin, before.origin);
    assert.equal(result.pathname, before.pathname);
    assert.equal(result.hash, before.hash);
    assert.deepEqual([...result.searchParams], [...before.searchParams, ['campaign','A&B + 中']]);
  }
});

